# DESIGN / EXAMPLE DATA ONLY — plausible musical content for mockups (not captured, not generated by Blocks).
# beats: 4/4, 4 bars = 16 beats, 92 BPM. pitch = MIDI note number.
CHORDS=["Dm9","G13","Cmaj9","A7♭9"]
VOICE={ "Dm9":[53,57,60,64], "G13":[53,59,64,69], "Cmaj9":[52,55,59,62], "A7♭9":[55,58,61,67]}
MEL={0:[(1.5,69,1),(2.5,67,.5),(3,65,1)],1:[(1.5,71,.5),(2,69,.5),(2.5,67,1.5)],2:[(1,64,.5),(1.5,67,.5),(2,71,1),(3,72,1)],3:[(1.5,73,.5),(2,70,.5),(2.5,69,1.5)]}
def piano():
    n=[]
    for b,c in enumerate(CHORDS):
        for p in VOICE[c]: n.append((b*4+0.0,1.4,p,84))
        for p in VOICE[c][1:]: n.append((b*4+2.5,0.9,p,70))
        for (s,p,d) in MEL[b]: n.append((b*4+s,d,p,92))
    return n
BASSL=[[38,41,45,48],[43,47,50,41],[36,40,43,47],[45,49,52,43]]
def bass():
    n=[]
    for b,bar in enumerate(BASSL):
        for i,p in enumerate(bar): n.append((b*4+i+(0.04 if i%2 else 0),0.85,p,96 if i==0 else 80))
    return n
def drums():  # (beat, row) rows: 0 hat,1 snare,2 kick
    h=[]
    for bar in range(4):
        for e in range(8): h.append((bar*4+e*0.5+(0.17 if e%2 else 0),0,0.6 if e%2 else 0.9))
        h+= [(bar*4+1,1,0.8),(bar*4+3,1,0.9),(bar*4,2,1),(bar*4+2.5,2,0.7)]
    return h
# a free-time phrase (no steady pulse) — seconds
def rubato():
    import math
    t=0;n=[];ps=[62,65,69,72,74,72,69,67,65,64,62,60,57,60,62]
    for i,p in enumerate(ps):
        d=0.35+0.5*abs(math.sin(i*1.7)); n.append((t,d*0.9,p,70+i%3*8)); t+=d
    return n,t
